import type { ComponentType } from 'react';
import type { OverlayComponentProps } from './context';

/**
 * THE overlay registry: id -> component, auto-collected from `overlays/<id>/index.tsx`
 * (default export). The folder name IS the overlay id. Objects reference these ids in
 * `src/content/objects/<id>.ts`. Add an overlay: create its folder; do NOT edit this file.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyOverlay = ComponentType<OverlayComponentProps<any>>;

const modules = import.meta.glob<{ default: AnyOverlay }>('./overlays/*/index.tsx', { eager: true });

export const OVERLAYS: Record<string, AnyOverlay> = Object.fromEntries(
  Object.entries(modules).map(([path, m]) => [path.split('/')[2] as string, m.default]),
);
